class DerivedNonce:
    def __init__(self):
        self.counter = 0
    def next(self, term):
        self.counter += 1
        return self.counter.to_bytes(12, "big")

old, new = DerivedNonce(), DerivedNonce()
print(old.next(3) == new.next(4))

def nonce(term, counter):
    return term.to_bytes(4, "big") + counter.to_bytes(8, "big")

print(nonce(7, 1).hex())

